package com.example.eac_backend_project.transport;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.mail.javamail.JavaMailSenderImpl;
import java.util.*;
import static com.example.eac_backend_project.transport.TransportValues.*;
import static com.example.eac_backend_project.transport.TransportAccess.fail;

@Service @Transactional
public class TransportPolicyService {
 private final TransportPolicies policies;private final TransportAccess access;private final TransportTimelines audit;private final JavaMailSender sender;
 public TransportPolicyService(TransportPolicies policies,TransportAccess access,TransportTimelines audit,JavaMailSender sender){this.policies=policies;this.access=access;this.audit=audit;this.sender=sender;}
 TransportPolicy policy(){return policies.findByScope("GLOBAL").orElseGet(()->policies.saveAndFlush(new TransportPolicy()));}
 public Map<String,Object> get(){access.require("TRANSPORT_SETTINGS");return describe(policy());}
 public Map<String,Object> rules(){access.current();TransportPolicy p=policy();return map("dvlaThresholds",thresholds(p.dvlaThresholds),"insuranceThresholds",thresholds(p.insuranceThresholds),"roadworthyThresholds",thresholds(p.roadworthyThresholds),"licenseThresholds",thresholds(p.licenseThresholds),"maintenanceDays",thresholds(p.maintenanceDays),"maintenanceKm",thresholds(p.maintenanceKm),"currency",p.currency,"timezone",p.timezone,"distanceUnit",p.distanceUnit,"vehicleCategories",split(p.vehicleCategories),"documentTypes",split(p.documentTypes),"componentCategories",split(p.componentCategories),"procurementCategories",split(p.procurementCategories),"allowMultipleVehiclesPerDriver",p.allowMultipleVehiclesPerDriver,"driverFuelEnabled",p.driverFuelEnabled,"driverMileageEnabled",p.driverMileageEnabled);}
 Map<String,Object> describe(TransportPolicy p){Map<String,Object> r=row(p);r.put("allowMultipleVehiclesPerDriver",p.allowMultipleVehiclesPerDriver);r.putAll(map("companyName",p.companyName,"currency",p.currency,"timezone",p.timezone,"distanceUnit",p.distanceUnit,"adminEmails",p.adminEmails,"faultEmails",p.faultEmails,"procurementEmails",p.procurementEmails,"supervisorEmails",p.supervisorEmails,"escalationEmails",p.escalationEmails,"dvlaThresholds",p.dvlaThresholds,"insuranceThresholds",p.insuranceThresholds,"roadworthyThresholds",p.roadworthyThresholds,"licenseThresholds",p.licenseThresholds,"maintenanceDays",p.maintenanceDays,"maintenanceKm",p.maintenanceKm,"vehicleCategories",p.vehicleCategories,"documentTypes",p.documentTypes,"componentCategories",p.componentCategories,"procurementCategories",p.procurementCategories,"reminderDays",p.reminderDays,"forecastMinReadings",p.forecastMinReadings,"forecastMaxAgeDays",p.forecastMaxAgeDays,"emailEnabled",p.emailEnabled,"inAppEnabled",p.inAppEnabled,"notifyDriver",p.notifyDriver,"notifyAdmin",p.notifyAdmin,"criticalEscalation",p.criticalEscalation,"driverFuelEnabled",p.driverFuelEnabled,"driverMileageEnabled",p.driverMileageEnabled));
  if(sender instanceof JavaMailSenderImpl smtp)r.put("smtp",map("host",smtp.getHost(),"port",smtp.getPort(),"sender",smtp.getUsername(),"authenticationConfigured",smtp.getUsername()!=null&&smtp.getPassword()!=null&&!smtp.getPassword().isBlank(),"tls",smtp.getJavaMailProperties().getProperty("mail.smtp.starttls.enable","false"),"ssl",smtp.getJavaMailProperties().getProperty("mail.smtp.ssl.enable","false")));
  return r;}
 public Map<String,Object> save(JsonNode data){access.require("TRANSPORT_SETTINGS");TransportPolicy p=policies.lock(policy().id).orElseThrow();revision(p,data);
  p.companyName=text(data,"companyName",180,true);p.currency=choice(data,"currency",Set.of("GHS"),"GHS");p.timezone=choice(data,"timezone",Set.of("Africa/Accra"),"Africa/Accra");p.distanceUnit=choice(data,"distanceUnit",Set.of("km"),"km");
  p.adminEmails=emails(text(data,"adminEmails",2000,false));p.faultEmails=emails(text(data,"faultEmails",2000,false));p.procurementEmails=emails(text(data,"procurementEmails",2000,false));p.supervisorEmails=emails(text(data,"supervisorEmails",2000,false));p.escalationEmails=emails(text(data,"escalationEmails",2000,false));
  p.dvlaThresholds=validateThresholds(text(data,"dvlaThresholds",100,true));p.insuranceThresholds=validateThresholds(text(data,"insuranceThresholds",100,true));p.roadworthyThresholds=validateThresholds(text(data,"roadworthyThresholds",100,true));p.licenseThresholds=validateThresholds(text(data,"licenseThresholds",100,true));p.maintenanceDays=validateThresholds(text(data,"maintenanceDays",100,true));p.maintenanceKm=validateThresholds(text(data,"maintenanceKm",100,true));
  p.vehicleCategories=categories(text(data,"vehicleCategories",2000,true),100,false);p.documentTypes=categories(text(data,"documentTypes",2000,true),80,true);p.componentCategories=categories(text(data,"componentCategories",2000,true),100,false);p.procurementCategories=categories(text(data,"procurementCategories",2000,true),100,false);
  p.reminderDays=integer(data,"reminderDays",true,1,30);p.forecastMinReadings=integer(data,"forecastMinReadings",true,2,100);p.forecastMaxAgeDays=integer(data,"forecastMaxAgeDays",true,1,3650);
  p.allowMultipleVehiclesPerDriver=bool(data,"allowMultipleVehiclesPerDriver",p.allowMultipleVehiclesPerDriver);
  p.emailEnabled=bool(data,"emailEnabled",p.emailEnabled);p.inAppEnabled=bool(data,"inAppEnabled",p.inAppEnabled);p.notifyDriver=bool(data,"notifyDriver",p.notifyDriver);p.notifyAdmin=bool(data,"notifyAdmin",p.notifyAdmin);p.criticalEscalation=bool(data,"criticalEscalation",p.criticalEscalation);p.driverFuelEnabled=bool(data,"driverFuelEnabled",p.driverFuelEnabled);p.driverMileageEnabled=bool(data,"driverMileageEnabled",p.driverMileageEnabled);
  var a=new TransportTimeline();a.actor=access.current();a.eventType="SETTINGS_UPDATED";a.description="Transport policy and notification settings updated";audit.save(a);policies.saveAndFlush(p);return describe(p);}
 private String categories(String value,int maxLength,boolean uppercase){var values=split(value);if(values.isEmpty()||values.size()>100||values.stream().anyMatch(v->v.length()>maxLength))throw fail(400,"Configure between one and 100 categories within the supported name length");String result=String.join(",",values);return uppercase?result.toUpperCase(Locale.ROOT):result;}
 static List<String> split(String text){return text==null?List.of():Arrays.stream(text.split(",")).map(String::trim).filter(s->!s.isBlank()).distinct().toList();}
 static List<Integer> thresholds(String text){return split(text).stream().map(Integer::valueOf).sorted(Comparator.reverseOrder()).toList();}
 private String validateThresholds(String text){try{var values=thresholds(text);if(values.isEmpty()||values.size()>15||values.stream().anyMatch(n->n<0||n>100000))throw new NumberFormatException();return String.join(",",values.stream().distinct().map(Object::toString).toList());}catch(Exception e){throw fail(400,"Alert thresholds must be comma-separated non-negative whole numbers");}}
}
